	walk('bathroom')
	# 1: find toothbrush
	find('toothbrush')
	# 2: grab toothbrush
	assert('close' to 'toothbrush')
		else: find('toothbrush')
	grab('toothbrush')
	# 3: find toothpaste
	find('toothpaste')
	# 4: grab toothpaste
	assert('close' to 'toothpaste')
		else: find('toothpaste')
	grab('toothpaste')
	# 5: apply toothpaste to toothbrush
	assert('toothbrush' in 'hands')
		else: find('toothbrush')
		else: grab('toothbrush')
	assert('toothpaste' in 'hands')
		else: find('toothpaste')
		else: grab('toothpaste')
	# 6: find faucet
	find('faucet')
	# 7: turn on faucet
	assert('close' to 'faucet')
		else: find('faucet')
	assert('faucet' is 'switchoff')
		else: switchoff('faucet')
	switchon('faucet')
	# 8: wet toothbrush under running water
	assert('toothbrush' in 'hands')
		else: find('toothbrush')
		else: grab('toothbrush')
	assert('close' to 'faucet')
		else: find('faucet')
	assert('faucet' is 'switchon')
		else: switchon('faucet')
	# 9: brush teeth (hold toothbrush at mouth)
	# 10: turn off faucet
	assert('close' to 'faucet')
		else: find('faucet')
	assert('faucet' is 'switchon')
		else: switchon('faucet')
	switchoff('faucet')
	# 11: put toothbrush back
	assert('toothbrush' in 'hands')
		else: find('toothbrush')
		else: grab('toothbrush')
	find('bathroomcounter')
	assert('close' to 'bathroomcounter')
		else: find('bathroomcounter')
	putback('toothbrush', 'bathroomcounter')
	# 12: put toothpaste back
	assert('toothpaste' in 'hands')
		else: find('toothpaste')
		else: grab('toothpaste')
	assert('close' to 'bathroomcounter')
		else: find('bathroomcounter')
	putback('toothpaste', 'bathroomcounter

